// CloudtainerML rev0023: dual-horizon memory retrieval toy.
// Synthetic C++17 probe. Not a paper reproduction.
#include <algorithm>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <random>
#include <string>
#include <vector>
struct Row{std::string regime,policy; int budget=0,n=0; double global=0, local=0, turns=0, success=0, utility=0;};
static std::string esc(const std::string&s){std::string o; for(char c:s){if(c=='"')o+="\\\""; else if(c=='\\')o+="\\\\"; else o+=c;} return o;}
static double clamp(double x,double a,double b){return std::max(a,std::min(b,x));}
static double rnd(std::mt19937_64&r,double a=0,double b=1){return std::uniform_real_distribution<double>(a,b)(r);} 
struct Eval{double global,local,turns,success,utility;};
static Eval eval(const std::string&reg,const std::string&pol,int budget,int seed){std::mt19937_64 rng(420020+seed*97+budget*31+reg.size()*13+pol.size()*19); double stage_shift=reg=="late_debug"?0.86:reg=="schema_exploration"?0.45:reg=="ambiguous_goal"?0.63:reg=="transfer_task"?0.72:0.25; double noise=reg=="noisy_memory"?0.82:0.35; double global=0,local=0,cost=budget;
if(pol=="no_memory"){global=0.22;local=0.20;cost=0;} else if(pol=="static_similarity"){global=0.45+0.12*rnd(rng);local=0.35+0.12*rnd(rng)-0.18*stage_shift;cost=budget*0.75;} else if(pol=="episode_only"){global=0.72+0.10*rnd(rng);local=0.24+0.06*rnd(rng);cost=budget*0.72;} else if(pol=="turn_only"){global=0.28+0.05*rnd(rng);local=0.70+0.10*rnd(rng)-0.12*noise;cost=budget*0.70;} else if(pol=="dual_horizon_static"){global=0.63+0.08*rnd(rng);local=0.60+0.10*rnd(rng)-0.06*stage_shift;cost=budget*0.95;} else if(pol=="dual_horizon_prm_toy"){global=0.67+0.10*rnd(rng);local=0.68+0.11*rnd(rng)+0.08*stage_shift-0.04*noise;cost=budget*1.15;} else if(pol=="oracle_horizon"){global=0.90;local=0.92;cost=budget*1.45;} global=clamp(global,0,1); local=clamp(local,0,1); double turns=clamp(9.0-3.2*global-4.0*local+2.0*noise+2.0*(stage_shift*(1-local)),1.0,12.0); double success=1.0/(1.0+std::exp(-((0.43*global+0.57*local)-0.48)*9.0)); double utility=2.7*success+0.6*global+0.9*local-0.06*turns-0.006*cost; return {global,local,turns,success,utility};}
static void add(Row&r,const Eval&e){r.n++;r.global+=e.global;r.local+=e.local;r.turns+=e.turns;r.success+=e.success;r.utility+=e.utility;}
int main(int argc,char**argv){std::string out="artifacts/probe-results/REV0023_HORIZON_MEMORY_RETRIEVAL_SMOKE.json"; if(argc>1)out=argv[1]; auto t0=std::chrono::high_resolution_clock::now(); std::vector<std::string> regimes={"schema_exploration","late_debug","ambiguous_goal","transfer_task","noisy_memory","easy"}; std::vector<std::string> policies={"no_memory","static_similarity","episode_only","turn_only","dual_horizon_static","dual_horizon_prm_toy","oracle_horizon"}; std::vector<int> budgets={4,8,16,32}; std::map<std::string,Row>rows; std::map<std::string,int>wins; for(auto&reg:regimes)for(int budget:budgets)for(int seed=0;seed<96;++seed){double best=-1e18;std::string bp; for(auto&pol:policies){auto e=eval(reg,pol,budget,seed); std::string key=reg+"|"+std::to_string(budget)+"|"+pol; if(!rows.count(key)){rows[key].regime=reg;rows[key].budget=budget;rows[key].policy=pol;} add(rows[key],e); if(e.utility>best){best=e.utility;bp=pol;}} wins[bp]++;} double seconds=std::chrono::duration<double>(std::chrono::high_resolution_clock::now()-t0).count(); std::ofstream f(out); f<<std::fixed<<std::setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0023\",\n  \"probe\": \"horizon_memory_retrieval\",\n  \"language\": \"c++17\",\n  \"is_paper_reproduction\": false,\n  \"taxonomy\": [\"agent-memory\", \"multi-horizon\", \"retrieval-policy\", \"native\"],\n"; f<<"  \"summary\": {\"row_count\": "<<rows.size()<<", \"seconds\": "<<seconds<<", \"primary_metric\": {\"name\": \"mean_utility\", \"direction\": \"higher_is_better\", \"winner_field\": \"winner_counts\"}, \"winner_counts\": {"; bool first=true; for(auto&kv:wins){if(!first)f<<", ";first=false;f<<"\""<<esc(kv.first)<<"\": "<<kv.second;} f<<"}, \"interpretation\": \"Separates episode/global and turn/local memory usefulness; tests whether a PRM-like local signal helps under stage shifts.\"},\n  \"rows\": [\n"; int c=0; for(auto&kv:rows){auto&r=kv.second;double n=std::max(1,r.n); if(c++)f<<",\n"; f<<"    {\"regime\": \""<<esc(r.regime)<<"\", \"budget\": "<<r.budget<<", \"policy\": \""<<esc(r.policy)<<"\", \"mean_global_strategy_score\": "<<r.global/n<<", \"mean_local_debug_score\": "<<r.local/n<<", \"mean_turns\": "<<r.turns/n<<", \"mean_success\": "<<r.success/n<<", \"mean_utility\": "<<r.utility/n<<"}";} f<<"\n  ]\n}\n"; std::cerr<<"wrote "<<out<<" rows="<<rows.size()<<"\n"; return 0;}
